          rows.push('<tr><td>'+escHtml(name)+'</td><td>'+escHtml(role)+'</td><td><input type="number" class="detail-time-weight-input" min="0" max="1000000" step="any" aria-label="员工权重" data-receiver="'+index+'" data-role="'+escHtml(role)+'" data-name="'+escHtml(name)+'" '+(result.weightSchemaVersion===1?'value="'+weight+'"':'value="" placeholder="—" data-weight-unrecorded="1"')+'></td></tr>');
